function NAT_BOX(S, n):
    result <- empty set
    prefix_all_in_S <- true
    for k from 0 to n-1:
        if prefix_all_in_S:
            add k to result          # all of 0..k-1 are in S
        if k not in S:
            prefix_all_in_S <- false # k breaks the prefix for k+1,...
    return result

